import{G as e,W as t,n,rt as r}from"./chunks/framework.CMPLvzN_.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"常识/地理/index.md","filePath":"常识/地理/index.md"}`),a={name:`常识/地理/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="中国平原" tabindex="-1">中国平原 <a class="header-anchor" href="#中国平原" aria-label="Permalink to “中国平原”">​</a></h2><p>东北平原是我国三大平原（东北平原、华北平原、华南平原）</p><p>东北平原由东北角的三江平原、北部的松嫩平原和南部的辽河平原三个亚区平原组成</p><h2 id="中国岛屿" tabindex="-1">中国岛屿 <a class="header-anchor" href="#中国岛屿" aria-label="Permalink to “中国岛屿”">​</a></h2><p>崇明岛是=被称为“长江门户、东海瀛洲”</p><h2 id="地球磁场" tabindex="-1">地球磁场 <a class="header-anchor" href="#地球磁场" aria-label="Permalink to “地球磁场”">​</a></h2><p>地球的地核分为内核和外核两部分，内核温度高为固体；外盒温度次之为流体，这些流体充满着铁和镍，带有磁性。再高温和地球自转的情况下会引起电磁感应，产生地磁。</p><p>极光的产生原因是<strong>地磁中的带电粒子</strong>进入大气层，使大气层分子或原子碰撞激发产生极光</p><p>与地磁暴有关的太阳爆发活动主要是<strong>太阳耀斑</strong>和<strong>日冕物质抛射</strong></p><p>地磁暴加强——&gt;高层大气被加热——&gt;大气膨胀扩散到更高空间——&gt;给航天器造成阻力——&gt;航天器减速——&gt;航天器降低高度——&gt;更稠密的大气——&gt;.....</p><h2 id="盆地" tabindex="-1">盆地 <a class="header-anchor" href="#盆地" aria-label="Permalink to “盆地”">​</a></h2><p><strong>盆地更容易富集油气资源</strong>，因为盆地通常是由地壳运动形成的低洼地带，其四周高、中央低的地形特点使得盆地内部容易形成封闭的构造环境，相比平原，更有利于油气资源的聚集。</p><p>塔里木盆地是大型封闭性山间盆地;华北渤海湾的盆地属于断陷盆地</p><p>盆地是指地球表面相对长时期沉降的区域，所以陆地和海洋中都有盆地造型。</p><p>岩溶盆地是大型溶蚀洼地</p><h2 id="天体" tabindex="-1">天体 <a class="header-anchor" href="#天体" aria-label="Permalink to “天体”">​</a></h2><p>金星又叫太白金星。清晨在东方天空出现叫<strong>启明星</strong>，晚间在西方天空出现叫<strong>长庚星</strong>或<strong>昏星</strong></p><h2 id="化石" tabindex="-1">化石 <a class="header-anchor" href="#化石" aria-label="Permalink to “化石”">​</a></h2><p>三叶虫生活时期是寒武纪到二叠纪</p><h2 id="四川地理" tabindex="-1">四川地理 <a class="header-anchor" href="#四川地理" aria-label="Permalink to “四川地理”">​</a></h2><p>地跨<strong>青藏高原</strong>（川西）、<strong>横断山脉</strong>（攀枝花）、<strong>云贵高原</strong>（宜宾、泸州等地与云贵加交界）、<strong>秦巴山地</strong>（广元到汉中经过秦岭）、<strong>四川盆地</strong>(成都)等几大地貌单元</p><p>四川的水能资源理论蕴藏量仅次于西藏</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};